-- ============================================================
-- AI Sathi Curriculum Tables
-- Run this script on any PostgreSQL database
-- ============================================================

-- STEP 1: Create Tables
-- ============================================================

CREATE TABLE IF NOT EXISTS school_app_aisathiclass (
    id          BIGSERIAL PRIMARY KEY,
    number      SMALLINT    NOT NULL UNIQUE,
    is_active   BOOLEAN     NOT NULL DEFAULT true,
    "order"     SMALLINT    NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS school_app_aisathisubject (
    id          BIGSERIAL PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    is_active   BOOLEAN      NOT NULL DEFAULT true,
    "order"     SMALLINT     NOT NULL DEFAULT 0,
    class_ref_id BIGINT      NOT NULL REFERENCES school_app_aisathiclass(id) ON DELETE CASCADE,
    CONSTRAINT unique_class_subject UNIQUE (class_ref_id, name)
);

CREATE TABLE IF NOT EXISTS school_app_aisathichapter (
    id          BIGSERIAL PRIMARY KEY,
    name        VARCHAR(300) NOT NULL,
    "order"     SMALLINT     NOT NULL DEFAULT 0,
    is_active   BOOLEAN      NOT NULL DEFAULT true,
    subject_id  BIGINT       NOT NULL REFERENCES school_app_aisathisubject(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_aisathisubject_class   ON school_app_aisathisubject(class_ref_id);
CREATE INDEX IF NOT EXISTS idx_aisathichapter_subject ON school_app_aisathichapter(subject_id);

-- ============================================================
-- STEP 2: Insert Records
-- ============================================================



-- ============================================================
-- STEP 3: Reset sequences so future inserts get correct IDs
-- ============================================================

SELECT setval(pg_get_serial_sequence('school_app_aisathiclass',   'id'), MAX(id)) FROM school_app_aisathiclass;
SELECT setval(pg_get_serial_sequence('school_app_aisathisubject',  'id'), MAX(id)) FROM school_app_aisathisubject;
SELECT setval(pg_get_serial_sequence('school_app_aisathichapter',  'id'), MAX(id)) FROM school_app_aisathichapter;
